Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -89,9 +89,9 @@
  function say(msg,good){toast.textContent=msg;toast.style.background=good?'#638f75':'#9b6471';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1050);person.classList.remove('bounce');void person.offsetWidth;person.classList.add('bounce');beep(good)}
  function answer(action){if(!active||!current)return;const ok=action===current.right;streak=ok?streak+1:0;score=Math.max(0,score+(ok?10+(streak>1?Math.min(streak,5)*2:0):-3));scoreEl.textContent=score;if(ok){say(current.yes,true);promptEl.textContent='Верный выбор! Новая ситуация…'}else{say(current.right==='wait'?'Она попросила паузу. Лучше дать ей время.':'Не совсем — прислушайся к её просьбе.',false);promptEl.textContent='Ничего страшного — попробуй снова'}setTimeout(()=>{if(active)next()},850)}
  buttons.forEach(b=>b.addEventListener('click',()=>answer(b.dataset.action)));
  function start(){clearInterval(timer);score=0;time=45;round=0;streak=0;active=true;scoreEl.textContent='0';timeEl.textContent=time;overlay.classList.add('hidden');next();timer=setInterval(()=>{time--;timeEl.textContent=time;progress.style.width=(time/45*100)+'%';if(time<=0)finish()},1000)}
- function finish(){active=false;clearInterval(timer);enable(false);overlay.classList.remove('hidden');$('#endTitle').textContent=score>=100?'Звезда заботы!':'Хорошая игра!';$('#endCopy').textContent=`Ты набрал${score===1?'':'а'} ${score} очков. Самое важное — спрашивать, замечать ответ и уважать личные границы.`;$('#start').textContent='Сыграть ещё';speech.innerHTML='Спасибо за игру! <small>Уважение делает общение приятным</small>';promptEl.textContent='Раунд завершён';progress.style.width='100%'}
+ function finish(){active=false;clearInterval(timer);enable(false);overlay.classList.remove('hidden');$('#endTitle').textContent=score>=100?'Звезда заботы!':'Хорошая игра!';$('#endCopy').textContent=`Твой результат: ${score} очков. Самое важное — спрашивать, замечать ответ и уважать личные границы.`;$('#start').textContent='Сыграть ещё';speech.innerHTML='Спасибо за игру! <small>Уважение делает общение приятным</small>';promptEl.textContent='Раунд завершён';progress.style.width='100%'}
  $('#start').addEventListener('click',start);$('#sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'🔊':'🔇';e.currentTarget.setAttribute('aria-label',soundOn?'Звук включён':'Звук выключен')});
 })();
 </script>
 </body>
